/// `(mayLoad, mayStore)` of a machine opcode.
pub fn memory_flags(opcode: u16) -> (bool, bool) {
    match MEMORY_FLAGS.binary_search_by_key(&opcode, |&(o, _)| o) {
        Ok(at) => (MEMORY_FLAGS[at].1 & 1 != 0, MEMORY_FLAGS[at].1 & 2 != 0),
        Err(_) => (false, false),
    }
}
